#include "odo.h"
#include "config.h"
#include "utils.h"
#include "hardware/pio.h"
#include "pico/critical_section.h"
#include "pico/stdlib.h"
#include <atomic>
#include "quadrature_encoder.pio.h"   // generated by pico_generate_pio_header

// Front encoder on PIO0, state machine 0. A/B must be consecutive GPIOs
// (A = FRONT_ENCODER_A_PIN, B = A+1); config uses GP10/GP11.
static PIO  s_pio = pio0;
static uint s_sm  = 0;
static long s_zero = 0;
// Guards the FIFO drain — both cores read the encoder.
static critical_section_t s_cs;

// Speed estimator state. s_speedMps is written on core1 and read on core0, so it
// is atomic; the sampling state below is touched only by odoSpeedTick()/Reset().
static std::atomic<float> s_speedMps{0.0f};
static float    s_lastSpeedDist = 0.0f;
static uint64_t s_lastSpeedUs   = 0;

void odoInit() {
  critical_section_init(&s_cs);
  pio_add_program(s_pio, &quadrature_encoder_program);
  // last arg 0 = max count rate (0 -> as fast as possible), same as robotour
  quadrature_encoder_program_init(s_pio, s_sm, FRONT_ENCODER_A_PIN, 0);
}

long odoCountRaw() {
  // Drain the FIFO, keep the newest entry.
  //
  // Two things this must get right, both learned the hard way:
  //
  // 1. BOUNDED. Read the level first and drain exactly that many. An unbounded
  //    `while (!fifo_empty)` can spin forever, because the PIO refills every ~10
  //    cycles — it does not stop to let you catch up. (The stock helper reads the
  //    level for this reason; its only flaw is ending with a BLOCKING get, which
  //    hangs if the state machine ever stops. Bounded and non-blocking is both.)
  //
  // 2. MUTUALLY EXCLUSIVE. Both cores read the encoder — core1 via poseUpdate,
  //    core0 via the state machine and the bench tools. Without a guard, one core
  //    can empty the FIFO between another's level-check and its get, which returns
  //    garbage rather than a count.
  static std::atomic<int32_t> s_lastCount{0};
  int32_t v;
  critical_section_enter_blocking(&s_cs);
  v = s_lastCount.load();
  int n = (int)pio_sm_get_rx_fifo_level(s_pio, s_sm);
  while (n-- > 0) v = (int32_t)pio_sm_get(s_pio, s_sm);
  s_lastCount.store(v);
  critical_section_exit(&s_cs);
  return v;
}

// ENCODER_SIGN (config.h §3) turns "however the A/B pair happens to be wired" into
// "positive means forward", so a reversed encoder is a one-line config flip rather
// than a rewiring job.
long odoCountSigned() {
  return ENCODER_SIGN * odoCountRaw();
}

void odoZero() {
  s_zero = odoCountSigned();
}

float odoDistanceM() {
  // NOTE: M_PER_COUNT must be calibrated (config.h) — it is 0.0 until you do,
  // which will (intentionally) read 0 distance and make the miscalibration obvious.
  return (float)(odoCountSigned() - s_zero) * M_PER_COUNT;
}

float odoDistanceCm() {
  return odoDistanceM() * 100.0f;
}

void odoSpeedReset() {
  s_speedMps.store(0.0f);
  s_lastSpeedDist = odoDistanceM();
  s_lastSpeedUs   = to_us_since_boot(get_absolute_time());
}

void odoSpeedTick() {
  const uint64_t now = to_us_since_boot(get_absolute_time());
  if (s_lastSpeedUs == 0) {          // first tick after boot: seed, don't emit
    odoSpeedReset();
    return;
  }
  const float dt = (float)(now - s_lastSpeedUs) * 1e-6f;
  if (dt < SPEED_SAMPLE_MIN_S) return;   // too soon — quantisation would swamp ds/dt

  const float dist = odoDistanceM();
  const float raw  = (dist - s_lastSpeedDist) / dt;
  s_lastSpeedDist  = dist;
  s_lastSpeedUs    = now;
  s_speedMps.store(utils::lowpass(s_speedMps.load(), raw, dt, SPEED_FILTER_TAU_S));
}

float odoSpeedMps() {
  return s_speedMps.load();
}
